import{_ as e,o as i,c as a,an as s}from"./chunks/framework.D0Z8TXKH.js";const c=JSON.parse('{"title":"Signal Example — ICA 4: Blind Source Separation","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/ica/signal_example_ica_geometry.md","filePath":"tutorials/teaching/ica/signal_example_ica_geometry.md","lastUpdated":null}'),n={name:"tutorials/teaching/ica/signal_example_ica_geometry.md"};function r(l,t,o,d,h,g){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="Signal-Example-—-ICA-4:-Blind-Source-Separation" tabindex="-1">Signal Example — ICA 4: Blind Source Separation <a class="header-anchor" href="#Signal-Example-—-ICA-4:-Blind-Source-Separation" aria-label="Permalink to &quot;Signal Example — ICA 4: Blind Source Separation {#Signal-Example-—-ICA-4:-Blind-Source-Separation}&quot;">​</a></h1><p>Interactive demonstration of <strong>Independent Component Analysis (ICA)</strong> — 3 sources, rotation geometry, and scatter plots.</p><div class="tip custom-block github-alert"><p class="custom-block-title">This is Part 4 of the ICA series. Start with [Part 2: What Is a Mixture?](signal_example_ica_mixture.md) or [Part 3: Mixing &amp; Unmixing](signal_example_ica_separation.md) first.</p><p></p></div><h2 id="What-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#What-it-shows" aria-label="Permalink to &quot;What it shows {#What-it-shows}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">True Sources (Row 1)</td><td style="text-align:right;">Three independent signals: S1 (oscillatory bursts, Gabor-shaped), S2 (blink artifacts), S3 (muscle burst)</td></tr><tr><td style="text-align:right;">EEG Recordings (Row 2)</td><td style="text-align:right;">The mixed signals as they would appear at electrodes — each is a weighted combination of all sources</td></tr><tr><td style="text-align:right;">Recovered Components (Row 3)</td><td style="text-align:right;">The unmixed signals, either via manual rotation sliders or the Auto-ICA (Infomax) algorithm</td></tr><tr><td style="text-align:right;">Scatter Plots</td><td style="text-align:right;">Three pairwise joint distributions (S1 vs S2, S1 vs S3, S2 vs S3) — see below</td></tr><tr><td style="text-align:right;">Excess Kurtosis</td><td style="text-align:right;">Displayed for sources and recovered components</td></tr></tbody></table><h3 id="The-Scatter-Plots" tabindex="-1">The Scatter Plots <a class="header-anchor" href="#The-Scatter-Plots" aria-label="Permalink to &quot;The Scatter Plots {#The-Scatter-Plots}&quot;">​</a></h3><p>The scatter plots are the most informative panel:</p><ul><li><p><strong>Independent, non-Gaussian signals</strong> → distinctive <strong>cross or T-shape</strong> (the signals are statistically independent)</p></li><li><p><strong>Mixed signals</strong> → correlated <strong>blob</strong> (everything jumbled together)</p></li><li><p><strong>Correctly unmixed</strong> → cross shape restored</p></li></ul><h2 id="Things-to-Try" tabindex="-1">Things to Try <a class="header-anchor" href="#Things-to-Try" aria-label="Permalink to &quot;Things to Try {#Things-to-Try}&quot;">​</a></h2><ol start="2"><li><p>Set all mixing angles &gt; 0° and watch the scatter plots collapse from crosses into blobs.</p></li><li><p>Drag the unmixing sliders manually to match the mixing angles — the sources reappear.</p></li><li><p>Reset unmixing angles to 0°, then click <strong>Infomax</strong> — ICA automatically recovers the sources.</p></li><li><p>Increase the <strong>Noise</strong> slider — Infomax still works because the blink and muscle sources are highly non-Gaussian.</p></li><li><p>Compare manual rotation with Infomax — Infomax finds a general unmixing matrix, not just a rotation.</p></li><li><p>Try <strong>Extended</strong> Infomax, which handles both sub-Gaussian and super-Gaussian sources.</p></li></ol><h2 id="Controls" tabindex="-1">Controls <a class="header-anchor" href="#Controls" aria-label="Permalink to &quot;Controls {#Controls}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Range</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Mix α (S1-S2)</td><td style="text-align:right;">0–90°</td><td style="text-align:right;">Rotation angle blending S1 and S2 into the recordings</td></tr><tr><td style="text-align:right;">Mix β (S1-S3)</td><td style="text-align:right;">0–90°</td><td style="text-align:right;">Rotation angle blending S1 and S3 into the recordings</td></tr><tr><td style="text-align:right;">Mix γ (S2-S3)</td><td style="text-align:right;">0–90°</td><td style="text-align:right;">Rotation angle blending S2 and S3 into the recordings</td></tr><tr><td style="text-align:right;">Unmix φ (S1-S2)</td><td style="text-align:right;">0–90°</td><td style="text-align:right;">Inverse rotation to recover S1/S2 (manual mode)</td></tr><tr><td style="text-align:right;">Unmix ψ (S1-S3)</td><td style="text-align:right;">0–90°</td><td style="text-align:right;">Inverse rotation to recover S1/S3 (manual mode)</td></tr><tr><td style="text-align:right;">Unmix χ (S2-S3)</td><td style="text-align:right;">0–90°</td><td style="text-align:right;">Inverse rotation to recover S2/S3 (manual mode)</td></tr><tr><td style="text-align:right;">Burst Freq</td><td style="text-align:right;">1–20 Hz</td><td style="text-align:right;">Frequency of the oscillatory source (S1)</td></tr><tr><td style="text-align:right;">Noise</td><td style="text-align:right;">0–1</td><td style="text-align:right;">Additive Gaussian noise on all sources</td></tr><tr><td style="text-align:right;">Infomax</td><td style="text-align:right;">—</td><td style="text-align:right;">Run standard Infomax ICA (Bell &amp; Sejnowski, 1995)</td></tr><tr><td style="text-align:right;">Extended</td><td style="text-align:right;">—</td><td style="text-align:right;">Run Extended Infomax (Lee et al., 1999)</td></tr></tbody></table><details class="details custom-block"><summary>Under the Hood — The Mathematics (click to expand)</summary><h3 id="The-Mixing-Model" tabindex="-1">The Mixing Model <a class="header-anchor" href="#The-Mixing-Model" aria-label="Permalink to &quot;The Mixing Model {#The-Mixing-Model}&quot;">​</a></h3><p>With N sources and N sensors, mixing is an N×N matrix multiplication. For 3 sources, we compose three pairwise 2D rotations (α, β, γ):</p><p><strong>Mixing</strong>: R₂₃(γ) · R₁₃(β) · R₁₂(α) · S <strong>Unmixing</strong>: R₁₂ᵀ(φ) · R₁₃ᵀ(ψ) · R₂₃ᵀ(χ) · M</p><p>When φ=α, ψ=β, χ=γ → perfect recovery.</p><h3 id="Why-Non-Gaussianity?" tabindex="-1">Why Non-Gaussianity? <a class="header-anchor" href="#Why-Non-Gaussianity?" aria-label="Permalink to &quot;Why Non-Gaussianity? {#Why-Non-Gaussianity?}&quot;">​</a></h3><p>ICA exploits the <strong>Central Limit Theorem in reverse</strong>: mixtures of independent signals are <em>more Gaussian</em> than the original signals. So finding the unmixing that maximises non-Gaussianity (measured by kurtosis or negentropy) recovers the independent sources.</p><ul><li><p><strong>Excess kurtosis = 0</strong>: Gaussian distribution</p></li><li><p><strong>Excess kurtosis &gt; 0</strong>: Super-Gaussian (sharp peaks, heavy tails — like blink spikes)</p></li><li><p><strong>Excess kurtosis &lt; 0</strong>: Sub-Gaussian (flat-topped distributions)</p></li></ul><p>The Infomax algorithm (Bell &amp; Sejnowski, 1995) used in EegFun maximises the total non-Gaussianity of the output components.</p></details><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./signal_example_ica_math">Part 1: Matrix Math Basics</a> — What is an Unmixing Matrix?</p></li><li><p><a href="./signal_example_ica_mixture">Part 2: What Is a Mixture?</a> — Simplest introduction to the problem</p></li><li><p><a href="./signal_example_ica_separation">Part 3: Mixing &amp; Unmixing</a> — 2-source introduction to ICA</p></li><li><p><a href="./signal_example_ica_clt">ICA: Central Limit Theorem</a> — Deep Dive: Why mixing creates Gaussian blobs</p></li><li><p><a href="./signal_example_ica_sphering">Part 5: Sphering (Whitening)</a> — Why ICA optimization is just finding an angle</p></li><li><p><a href="./signal_example_ica_optimization">Part 6: Inside the Black Box</a> — The optimization landscape and gradient ascent</p></li><li><p><a href="./../../preprocessing/ica">ICA Demo</a> — Full ICA workflow on real EEG data</p></li><li><p><a href="https://eeglab.org/tutorials/06_RejectArtifacts/RunICA.html" target="_blank" rel="noreferrer">EEGLAB: Running ICA</a> — Practical guide to ICA in EEGLAB</p></li><li><p><a href="https://arnauddelorme.com/ica_for_dummies/" target="_blank" rel="noreferrer">ICA for Dummies</a> — Arnaud Delorme&#39;s accessible introduction to ICA</p></li><li><p>Bell, A. J., &amp; Sejnowski, T. J. (1995). An information-maximization approach to blind separation. <em>Neural Computation</em>, <em>7</em> (6), 1129–1159.</p></li><li><p>Hyvärinen, A., &amp; Oja, E. (2000). Independent component analysis: algorithms and applications. <em>Neural Networks</em>, <em>13</em> (4-5), 411–430.</p></li></ul><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_ica_geometry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,17)])])}const m=e(n,[["render",r]]);export{c as __pageData,m as default};
